using EduVerse.Core.Common;

namespace EduVerse.Core.Lessons;

public static class LessonSamples
{
    public static (string Title, string Subject, string Text) Get(TeachLanguage language) => language switch
    {
        TeachLanguage.Spanish => ("La fotosíntesis", "Ciencias naturales",
            "La fotosíntesis es el proceso mediante el cual las plantas, las algas y algunas bacterias transforman la energía de la luz en energía química, que almacenan en forma de glucosa. Este proceso tiene lugar principalmente en las hojas, dentro de unos orgánulos llamados cloroplastos, que contienen un pigmento verde, la clorofila, capaz de absorber la luz solar.\n\nPara realizar la fotosíntesis, la planta necesita agua, que absorbe a través de las raíces, y dióxido de carbono, que entra en las hojas por unos pequeños poros llamados estomas. Gracias a la energía de la luz, la planta combina estas sustancias y produce glucosa, que utiliza para crecer, y oxígeno, que libera a la atmósfera.\n\nLa fotosíntesis es fundamental para la vida en la Tierra, porque produce el oxígeno que respiramos y es la base de casi todas las cadenas alimentarias, ya que los animales herbívoros se alimentan de plantas y los carnívoros, a su vez, de herbívoros. Además, al absorber dióxido de carbono, las plantas ayudan a regular el clima del planeta."),
        TeachLanguage.French => ("La photosynthèse", "Sciences de la vie",
            "La photosynthèse est le processus par lequel les plantes, les algues et certaines bactéries transforment l'énergie de la lumière en énergie chimique, qu'elles stockent sous forme de glucose. Ce processus a lieu principalement dans les feuilles, à l'intérieur d'organites appelés chloroplastes, qui contiennent un pigment vert, la chlorophylle, capable d'absorber la lumière du soleil.\n\nPour réaliser la photosynthèse, la plante a besoin d'eau, qu'elle absorbe par les racines, et de dioxyde de carbone, qui entre dans les feuilles par de petits pores appelés stomates. Grâce à l'énergie de la lumière, la plante combine ces substances et produit du glucose, qu'elle utilise pour grandir, et de l'oxygène, qu'elle libère dans l'atmosphère.\n\nLa photosynthèse est essentielle à la vie sur Terre, car elle produit l'oxygène que nous respirons et elle est à la base de presque toutes les chaînes alimentaires, puisque les herbivores se nourrissent de plantes et les carnivores, à leur tour, d'herbivores. De plus, en absorbant le dioxyde de carbone, les plantes aident à réguler le climat de la planète."),
        TeachLanguage.Catalan => ("La fotosíntesi", "Ciències naturals",
            "La fotosíntesi és el procés mitjançant el qual les plantes, les algues i alguns bacteris transformen l'energia de la llum en energia química, que emmagatzemen en forma de glucosa. Aquest procés té lloc principalment a les fulles, dins d'uns orgànuls anomenats cloroplasts, que contenen un pigment verd, la clorofil·la, capaç d'absorbir la llum del sol.\n\nPer fer la fotosíntesi, la planta necessita aigua, que absorbeix a través de les arrels, i diòxid de carboni, que entra a les fulles per uns petits porus anomenats estomes. Gràcies a l'energia de la llum, la planta combina aquestes substàncies i produeix glucosa, que fa servir per créixer, i oxigen, que allibera a l'atmosfera.\n\nLa fotosíntesi és fonamental per a la vida a la Terra, perquè produeix l'oxigen que respirem i és la base de gairebé totes les cadenes alimentàries, ja que els animals herbívors s'alimenten de plantes i els carnívors, al seu torn, d'herbívors. A més, en absorbir diòxid de carboni, les plantes ajuden a regular el clima del planeta."),
        _ => ("Photosynthesis", "Natural science",
            "Photosynthesis is the process by which plants, algae and some bacteria transform the energy of light into chemical energy, which they store as glucose. This process takes place mainly in the leaves, inside small organelles called chloroplasts, which contain a green pigment, chlorophyll, that is able to absorb sunlight.\n\nTo carry out photosynthesis, the plant needs water, which it absorbs through its roots, and carbon dioxide, which enters the leaves through tiny pores called stomata. Thanks to the energy of light, the plant combines these substances and produces glucose, which it uses to grow, and oxygen, which it releases into the atmosphere.\n\nPhotosynthesis is essential for life on Earth, because it produces the oxygen we breathe and it is the basis of almost every food chain, since herbivores feed on plants and carnivores, in turn, feed on herbivores. Moreover, by absorbing carbon dioxide, plants help to regulate the climate of the planet."),
    };
}
